use IO.Std.write_line
use Ghul.Pipes.map
use Ghul.Pipes.filter
use Ghul.Pipes.reduce

// see pipes examples for more details

// map
let doubled = [1, 2, 3, 4, 5] |> map(x => x * 2)
write_line("doubled: {doubled}")

// filter
let evens = [1, 2, 3, 4, 5] |> filter(x => x % 2 == 0)
write_line("evens: {evens}")

// reduce
let sum = [1, 2, 3, 4, 5] |> reduce(0, (acc, x) => acc + x)
write_line("sum: {sum}")

use IO.Std.write_line

// expression bodied functions and some support for
// expression oriented programming help in writing
// pure functions
let list = [1, 2, 3, 4, 5]

// lists can be subscripted to read an element at a given index
let element_3 = list[3]

// but lists are immutable, so this will cause a compile time
// error if uncommented:
// list[3] = 10;

let tuple = (1, 2, 3, 4, 5)

// tuples can be destructured
let (a, b, c, d, e) = tuple

// individual members can be accessed with dot notation
let first = tuple.`1

// but tuples are immutable, so members cannot be assigned to:
// tuple.`1 = 10; // compile time error

let classify = n =>
    if n == 0 then
        "Zero"
    elif n % 2 == 0 /\ n < 0 then
        if n % 5 == 0 then "Negative even and multiple of 5"
        else "Negative even" fi
    elif n % 2 != 0 /\ n < 0 then
        if n % 5 == 0 then "Negative odd and multiple of 5"
        else "Negative odd" fi
    elif n % 2 == 0 then
        if n % 5 == 0 then "Positive even and multiple of 5"
        else "Positive even" fi
    else
        if n % 5 == 0 then "Positive odd and multiple of 5"
        else "Positive odd" fi
    fi

write_line("classifyNumber(-10): {classify(-10)}")
write_line("classifyNumber(-3): {classify(-3)}")
write_line("classifyNumber(0): {classify(0)}")
write_line("classifyNumber(4): {classify(4)}")
write_line("classifyNumber(25): {classify(25)}")

use IO.Std.write_line

// mutual recursion is slightly awkward for anonymous functions because
// of the forward reference. one way is to pass the other function in as
// an argument:
let is_even = (n, is_odd) => if n == 0 then true else is_odd(n - 1) fi
let is_odd = n rec => if n == 0 then false else is_even(n - 1, rec) fi

write_line("even(10): {is_even(10, is_odd)}")
write_line("odd(10): {is_odd(10)}")

// another way is to declare one of the functions as a mutable variable
// and assign the anonymous function to it after the other is defined:
let odd mut = _

let even = n => if n == 0 then true else odd(n - 1) fi
odd = n => if n == 0 then false else even(n - 1) fi

write_line("even(10): {even(10)}")
write_line("odd(10): {odd(10)}")

// with named functions, mutual recursion doesn't need a workaround:
named_even(n: int) -> bool => if n == 0 then true else named_odd(n - 1) fi
named_odd(n: int) -> bool => if n == 0 then false else named_even(n - 1) fi

use IO.Std.write_line
use Ghul.Pipes.map

// immutable data structures
let list = [1, 2, 3, 4, 5]

let doubled = list |> map(x => x * 2)

// original list is still the same:
write_line("list: {list |> $}")

// pure functions
let add = (x, y) => x + y
write_line("add(5, 3): {add(5, 3)}")

use IO.Std.write_line

// higher-order functions:

// a generic higher-order function:
apply[T](f: T -> T, x: T) -> T =>
    f(x)

// anonymous functions to pass to it:
let times_2 = x => x * 2
write_line("apply(times_2, 5): {apply(times_2, 5)}")

let square = x => x * x
write_line("apply(square, 5): {apply(square, 5)}")

// a higher-order function that takes a function:
let apply_twice = (f, x) => f(f(x))
write_line("apply_twice(times_2, 5): {apply_twice(times_2, 5)}")

// and one that returns a function:
let create_apply_twice = f => x => f(f(x))
let apply_twice_times_2 = create_apply_twice(times_2)

write_line("apply_twice_times_2(5): {apply_twice_times_2(5)}")

use IO.Std.write_line

let add = (x, y) => x + y

let add_5 = y => add(5, y)
write_line("add_5(3): {add_5(3)}")

let add_10 = y => add(10, y)
write_line("add_10(3): {add_10(3)}")

use IO.Std.write_line
use Collections.LIST

// note the various 'i's and 'g's in this example - there are no name clashes
// because each 'i' and 'g' is in a different scope.
entry() is
    // f is an anonymous function:
    let f = i => i * 2

    // its type is int -> int
    assert f.get_type() == typeof int -> int

    // it returns its integer argument times two:
    assert f(123) == 123 * 2

    for i in 1::10 do
        write_line("f({i}) = {f(i)}")
    od

    // list_of_gs is a list of 2-tuples, each one having an integer and a function element.
    // its element type doesn't need to be written out - the compiler infers it from the
    // add() call below:
    let list_of_gs = LIST()

    for i in 1::10 do
        // create a function that captures a value - in this case the loop variable i
        let g = () => i

        // g is a parameterless function that returns an int:
        assert g.get_type() == typeof () -> int

        // when we call g, it returns the value of i when g was created:
        assert g() == i

        // store that function in our list for use later:
        list_of_gs.add((i, g))

        // the last value in the list is the tuple we just added:
        assert list_of_gs[list_of_gs.count-1] =~ (i, g)
    od

    for (i, g) in list_of_gs do
        // each saved g still returns the same value of i that
        // it captured when it was created:
        assert i == g()

        write_line("g that captured i when it was {i} is a {g} that returns {g()}")
    od

    // a closure can also reassign a mut variable from an outer scope, so bump
    // and peek share one counter rather than each holding a copy of it:
    let counter mut = 0

    let bump = n is
        counter = counter + n
    si

    let peek = () => counter

    bump(1)
    bump(2)
    bump(3)

    assert peek() == 6
    assert counter == 6

    write_line("counter = {counter}, peek() = {peek()}")
si

// make a type available in this scope without qualification
use Collections.Iterable

// and a static method:
use IO.Std.write_line

// Ghul.Pipes has a global function for every way of manipulating a sequence
// of elements - map, filter, reduce, and so on:
use Ghul.Pipes

entry() is
    // ghūl has anonymous functions:
    let f = (i: int) -> string => "i is {i}"
    write_line("f(123) = {f(123)}")

    // anonymous functions infer their return type, if it is not explicit:
    let g = (j: int) => "j is {j}"
    write_line("g(456) = {g(456)}")

    // anonymous functions can have a block body:
    let h = (k: int) is
        let result mut = "k is "
        result = "{result}{k}"
        return result // return type is inferred here
    si

    write_line("h(789) = {h(789)}")

    // anonymous functions can capture values from outer lexical scopes -
    // in this case the anonymous functions f, g and h are captured:
    let closure = (i, j, k) => "{f(i)}, {g(j)}, {h(k)}"
    write_line("captured values: {closure(111, 222, 333)}")

    // anonymous functions can be nested, and their frames live on after they return:
    let outer = () is
        let message = "hello"

        let middle = () is
            let inner = () => message

            return inner
        si

        return middle
    si

    let hello_inner_from_outer = outer()()()
    write_line("call inner() returned by outer(): {hello_inner_from_outer}")

    // '[' and ']' construct an immutable list (Collections.List[T], where T is inferred from the element type):
    let list = [1, 2, 3, 4, 5, 6]

    // '$' renders any Collections.Iterable[T] as a string:
    write_line("list: {list |> $}")

    // '..' constructs an iterable integer range, inclusive of the first element and exclusive of the last:
    let exclusive_range = 0..10
    write_line("exclusive int range: {exclusive_range |> $}")

    // '::' constructs an iterable integer range, inclusive of the first and last elements:
    let inclusive_range = 1::10
    write_line("inclusive int range: {inclusive_range |> $}")

    // the thread-first operator '|>' calls a function with the value on its left as
    // the first argument: 'x |> f(a)' is 'f(x, a)'. Chained, it reads left to right:
    // 'x |> f(a) |> g(b)' is 'g(f(x, a), b)'

    // filter passes only those elements that meet a supplied filter condition:
    let even = 1::8 |> filter(i => is_even(i))
    write_line("even numbers: {even}")

    // you generally don't need explicit argument types for anonymous functions when they're
    // passed as arguments, as their types can be inferred from context:
    let odd = [1, 2, 3, 4, 5, 6, 7, 8] |> filter(i => is_odd(i))
    write_line("odd numbers: {odd}")

    // map transforms elements according to a supplied function:
    let times_3 = [1, 2, 3, 4, 5, 6, 7, 8] |> map(i => i * 3)
    write_line("times 3: {times_3}")

    // if you hover the mouse over the call to map, you'll see the full inferred function signature:
    let strings = 1..9 |> map(i => "'{i}'")
    write_line("map to strings: {strings}")

    let strings_with_lengths =
        ["one", "two", "three", "four", "horse", "weevil", "six"] |>
            map(s => (s, s.length))

    write_line("strings with lengths: {strings_with_lengths}")

    // pipes are iterable, so you can loop over them with 'for':
    for (position, value) in [1, 2, 3] |> map(i => i * 3) |> index() do
        write_line("result #{position + 1} is {value}")
    od

    // strings are iterable:
    let upper = "hello world" |> map(c => char.to_upper(c)) |> join("")
    write_line("upper cased: '{upper}'")

    // reduce accumulates a running value according to a supplied function:
    let folded = [1, 2, 3, 4, 5, 6, 7, 8] |> reduce(0, (r, e) => r + e)
    write_line("sum with reduce: {folded}")

    // sum and product total a sequence without a starting value:
    let total = [1, 2, 3, 4, 5, 6, 7, 8] |> sum()
    let factorial = 1::6 |> product()
    write_line("sum is: {total}, 6! is: {factorial}")

    // you can chain multiple calls in a fluent style:
    let count_greater_than_3 =
        [1, 2, 3, 4, 5, 6, 7, 8] |>
            filter(i => i > 3) |>
            count()

    write_line("count of elements > 3 is: {count_greater_than_3}")

    let sum_double_odd =
        [1, 2, 3, 4, 5, 6, 7, 8] |>
            filter(i => is_odd(i)) |>
            map(i => i * 2) |>
            reduce(0, (r, e) => r + e)

    write_line("sum of doubled odd numbers is: {sum_double_odd}")

    let first_3 = [1, 2, 3, 4, 5, 6, 7, 8] |> take(3)
    write_line("take first 3: {first_3}")

    let skip_3 = [1, 2, 3, 4, 5, 6, 7, 8] |> skip(3)
    write_line("skip first 3: {skip_3}")

    let three_from_middle =
        [1, 2, 3, 4, 5, 6, 7, 8] |>
            skip(3) |>
            take(3)

    write_line("take 3 from the middle: {three_from_middle}")

    let sum_three_from_middle =
        [1, 2, 3, 4, 5, 6, 7, 8] |>
            skip(3) |>
            take(3) |>
            reduce(0, (r, e) => r + e)

    write_line("sum of 3 from the middle: {sum_three_from_middle}")

    // zip combines two sequences into a single sequence of pairs/2-tuples
    let zipped =
        [1, 2, 3, 4, 5, 6, 7, 8] |>
            zip([8, 7, 6, 5, 4, 3, 2, 1])

    write_line("zip of two sequences is: {zipped}")

    // or into a sequence where each element is derived by passing the
    // left + right elements to a supplied function:
    let zip_map =
        [1, 2, 3, 4, 5, 6, 7, 8] |>
            zip([8, 7, 6, 5, 4, 3, 2, 1], (l, r) => l + r)

    write_line("sum of zipped is: {zip_map}")

    // cat concatenates two pipes into a single sequence
    let concatenated =
        [1, 2, 3, 4, 5, 6, 7, 8] |>
            cat([8, 7, 6, 5, 4, 3, 2, 1])

    write_line("concatenated is: {concatenated}")

    // a chain closes off into a collection by constructing one from it:
    let squares = 1::5 |> map(i => i * i) |> ARRAY()
    write_line("squares: {squares}")

    // and into text with string, which puts a separator between elements:
    let dashed = 1::5 |> string("-")
    write_line("dashed: {dashed}")

    // index() tags each element with its 0-based index in the sequence:
    let indexed = ["cat", "dog", "fish", "zebra", "ameoba"] |> index()

    write_line("indexed: {indexed}")
si

is_odd(i: int) -> bool => i & 1 != 0
is_even(i: int) -> bool => i & 1 == 0

use IO.Std.write_line
use Ghul.Pipes.from
use Ghul.Pipes.take

// a list comprehension builds an array: the element first, then for
// clauses, each optionally followed by if clauses

entry() is
    let squares = [x * x for x in 1::5]
    write_line("squares: {squares}")

    // each for clause sees the variables of the clauses before it, and an
    // if clause keeps only the elements its condition holds for:
    let triples = [
        (a, b, c)
        for a in 1::20
        for b in a::20
        for c in b::20
        if a * a + b * b == c * c
    ]
    write_line("right triangles: {triples}")

    // an if clause narrows what it tests, so name is a string here:
    let names: string?[] = ["ada", null, "grace"]
    let lengths = [name.length for name in names if name?]
    write_line("name lengths: {lengths}")

    // in braces the comprehension is lazy: a pipe that works out each element
    // only when it is read, so its source can go on forever:
    let odd_squares = {n * n for n in from(1) if n % 2 == 1}
    write_line("first odd squares: {odd_squares |> take(4)}")
si

use IO.Std.write_line

entry() is
    reading_optionals()
    presence_narrowing()
    coalescing()
    safe_member_access()
si

// T? holds a T, or nothing. a T can be used where a T? is expected, but a
// T? has to be checked for a value, with if let, '?', '!' or '??', before
// it can be used where a T is expected.

// a known scheme gives its port, and any other gives null:
lookup_port(scheme: string) -> int? =>
    case scheme
    when "http" then 80
    when "https" then 443
    when "ssh" then 22
    else null
    esac

reading_optionals() is
    let http = lookup_port("http")
    let smtp = lookup_port("smtp")

    // if let enters its branch only when a value is present, and
    // gives the present value a non-optional name to read directly
    if let port = http then
        write_line("http listens on port {port}")
    fi

    if let port = smtp then
        write_line("smtp listens on port {port}")
    else
        write_line("smtp has no well-known port")
    fi
si

presence_narrowing() is
    let ssh = lookup_port("ssh")

    // the '?' presence test narrows the optional to non-optional for
    // the rest of the branch, so it reads without any unwrapping
    if ssh? then
        write_line("ssh listens on port {ssh}")
    fi
si

coalescing() is
    // '??' gives a fallback for an absent value, and only evaluates it when
    // it's needed. a chain of them stays optional until a value that isn't
    // optional ends it, here the literal 21:
    let ftp_port = lookup_port("ftp") ?? lookup_port("ftps") ?? 21

    write_line("ftp falls back to port {ftp_port}")
si

// manager is optional: the head of the tree reports to nobody
class EMPLOYEE(name: string, manager: EMPLOYEE?)

safe_member_access() is
    let ceo = EMPLOYEE("Ada", null)
    let lead = EMPLOYEE("Bjarne", ceo)
    let dev = EMPLOYEE("Grace", lead)

    // '?.' reads a member when there is a value, and gives null when there
    // isn't, so a chain stops at the first absent value. '??' then gives a
    // plain string:
    write_line("Grace's skip manager is {dev.manager?.manager?.name ?? "nobody"}")
    write_line("Bjarne's skip manager is {lead.manager?.manager?.name ?? "nobody"}")
si

use IO.Std.write_line

// an async function returns Tasks.TASK[T], or Tasks.TASK when there's no
// result. every task here completes straight away, so each run prints the
// same thing.

// a T returned from a function that returns Tasks.TASK[T] is wrapped in a
// completed task:
double_async(x: int) -> Tasks.TASK[int] => x * 2

add_async(x: int, y: int) -> Tasks.TASK[int] => x + y

// await waits for a task and gives its result:
compute() -> Tasks.TASK[int] is
    let a = await double_async(10)
    let b = await double_async(a)
    let c = await add_async(a, b)

    return c
si

// a return after an await leaves the function, as it would anywhere else:
classify(n: int) -> Tasks.TASK[string] is
    let doubled = await double_async(n)

    if doubled > 50 then
        return "big"
    fi

    return "small"
si

side_effect(label: string) -> Tasks.TASK is
    write_line("side effect: {label}")

    return Tasks.TASK.completed_task
si

// await on its own waits for a task and discards any result:
run_side_effects() -> Tasks.TASK is
    await side_effect("first")
    await side_effect("second")

    return
si

// await can be used inside a loop:
sum_doubled(xs: Collections.List[int]) -> Tasks.TASK[int] is
    let total mut = 0

    for x in xs do
        let y = await double_async(x)
        total = total + y
    od

    return total
si

// awaiting a faulted task throws its exception, so the function that awaits
// it returns a faulted task too. Tasks.TASK.from_exception makes one:
checked_divide(a: int, b: int) -> Tasks.TASK[int] is
    if b == 0 then
        return Tasks.TASK.from_exception(
            System.InvalidOperationException("division by zero")
        )
    fi

    return a / b
si

divide_then_double(a: int, b: int) -> Tasks.TASK[int] is
    let q = await checked_divide(a, b)
    let result = await double_async(q)

    return result
si

entry() is
    write_line("compute() = {compute().result}")

    write_line("classify(10) = {classify(10).result}")
    write_line("classify(100) = {classify(100).result}")

    run_side_effects().wait()

    write_line("sum_doubled = {sum_doubled([1, 2, 3, 4]).result}")

    write_line("divide_then_double(20, 5) = {divide_then_double(20, 5).result}")

    // .result on a faulted task throws an AggregateException, and
    // get_base_exception gets the original exception from it:
    try
        let result = divide_then_double(10, 0).result
        write_line("divide_then_double(10, 0) unexpected: {result}")
    catch ex: System.AggregateException
        let cause = ex.get_base_exception()

        write_line("divide_then_double(10, 0) caught: {cause.message}")
    yrt
si

use IO.Std.write_line

class BOX[T](value: T)
class PAIR[A, B](first: A, second: B)

// a generic class's type arguments come from its constructor's arguments:
let int_box = BOX(42)
let string_box = BOX("hello")
let pair = PAIR(123, "hello")

write_line("int_box.value: {int_box.value}")
write_line("string_box.value: {string_box.value}")
write_line("pair: ({pair.first}, {pair.second})")

// inference nests through the call tree:
let nested = BOX(BOX(7))
write_line("nested.value.value: {nested.value.value}")

let mixed = PAIR(BOX(1), BOX("two"))
write_line("mixed: ({mixed.first.value}, {mixed.second.value})")

use IO.Std.write_line

// an array literal's element type is its elements' type where they
// all agree, and their closest common supertype where they don't:
let ints = [1, 2, 3]
let strings = ["one", "two", "three"]

write_line("ints: {ints |> $}")
write_line("strings: {strings |> $}")

// a tuple's element types come from its element expressions:
let person = ("alice", 30)
write_line("person: ({person.`0}, {person.`1})")

// nested:
let nested = (("alice", 30), [1, 2, 3])
write_line("nested.`0.`0: {nested.`0.`0}")

use IO.Std.write_line

// destructuring gives each variable the type of its part of the value:
let person = ("alice", 30)
let (name, age) = person
write_line("name: {name} ({name.get_type()}), age: {age} ({age.get_type()})")

// works for nested tuples too:
let ((first, second), third) = (("a", "b"), "c")
write_line("first: {first}, second: {second}, third: {third}")

use IO.Std.write_line
use Ghul.Pipes.map
use Ghul.Pipes.filter
use Ghul.Pipes.reduce

// a function literal passed to a call takes its parameter types
// from the function type the call expects.

// map: x is an int, from the source's element type:
let doubled = [1, 2, 3] |> map(x => x * 2)
write_line("doubled: {doubled}")

// filter: x is an int here too:
let even = [1, 2, 3, 4, 5, 6] |> filter(x => x % 2 == 0)
write_line("even: {even}")

// reduce: acc comes from the seed, and x from the source:
let sum = [1, 2, 3, 4, 5] |> reduce(0, (acc, x) => acc + x)
write_line("sum: {sum}")

// each call in a chain passes its types on to the next:
let labelled = [1, 2, 3] |> map(n => "[{n}]") |> reduce("", (acc, s) => "{acc}{s}")
write_line("labelled: {labelled}")

use IO.Std.write_line
use Ghul.Pipes.map

// a function literal's parameter types can come from where it is used,
// when its body alone doesn't say what they are:

let add = (x: int, y: int) => x + y

// y has no written type, and is an int because it's passed to add:
let add_5 = y => add(5, y)
write_line("add_5(3): {add_5(3)}")

// s is a string, from the list it is mapped over:
let lengths = ["one", "fourteen", "five"] |> map(s => s.length)
write_line("lengths: {lengths}")

use IO.Std.write_line

// x's type comes from both the body, which reads x.length, and the
// call, which passes a string. neither is enough on its own:
let f = x => x.length
write_line("f(\"hello\"): {f("hello")}")

use IO.Std.write_line

class BOX[T](value: T)

make_multiplier(n: int) -> int -> int =>
    x => x * n

// a comes from curried_add(5), and b from add_5(3):
let curried_add = a => b => a + b
let add_5 = curried_add(5)
write_line("add_5(3): {add_5(3)}")
write_line("add_5(20): {add_5(20)}")

// make_multiplier returns a closure that captures n:
let times_7 = make_multiplier(7)
write_line("times_7(6): {times_7(6)}")

// BOX's T comes from n, and make_box's return type from BOX:
let make_box = n => BOX(n)
let boxed = make_box(42)
write_line("boxed.value: {boxed.value}")

use IO.Std.write_line

// a generic global function's type arguments come from its arguments,
// so [T] is not normally needed at the call site:
apply[T](f: T -> T, x: T) -> T => f(x)
transform[A, B](f: A -> B, x: A) -> B => f(x)

// T = int from times_2 and 5:
let times_2 = x => x * 2
write_line("apply(times_2, 5): {apply(times_2, 5)}")

// A = int, B = string from the function literal and the value:
let stringified = transform(n => "<{n}>", 42)
write_line("transform(...): {stringified}")
